import { event_registers_members_list } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    eventInfo: Object,
    Eventlist: Boolean
  },
  data() {
    return {
      loading: false,
      items: []
    };
  },
  watch: {
    Eventlist: {
      async handler() {
        if (this.Eventlist == true) {
          this.list_users();
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async list_users() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(event_registers_members_list, {
          input: {
            event_id: this.eventInfo.event_id,
            nextToken: null,
            limit: 100
          }
        }));
        this.items = [];
        var response = result.data.event_registers_members_list;
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.items = response.data;
        } else {
          this.items = [];
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
